class OneTransferByIdTest extends BootedApplicationTest {

	private static final String TRANSFERS = "/api/transfers";

	private static final long SOURCE_ACCOUNT = 1L;

	private static final long DESTINATION_ACCOUNT = 2L;

	private static final long TRANSFER = 31L;

	private static final Instant REQUESTED_AT = Instant.parse("2026-09-06T09:41:00Z");

	@Autowired
	private JdbcTemplate jdbc;

	/**
	 * Emptied and reopened in one method rather than two: JUnit promises no order between two
	 * {@code @BeforeEach} methods, and opening the Accounts before the delete would leave the
	 * insert below without the rows its foreign keys point at.
	 */
